package com.fulllock.app;
import android.app.*;import android.content.*;import android.os.*;import android.util.AtomicFile;import android.widget.*;import org.json.*;import java.io.*;import java.lang.ref.WeakReference;import java.util.concurrent.atomic.AtomicBoolean;
/** Local, allowlisted diagnostics only. No error messages, jobs, coordinates, IDs or credentials. */
final class AppIssues {
 private static Context app;private static WeakReference<Activity> resumed=new WeakReference<>(null);private static final Handler main=new Handler(Looper.getMainLooper());private static final AtomicBoolean crashing=new AtomicBoolean();private static boolean showing;private static AlertDialog activeDialog;
 static void install(Application application){app=application.getApplicationContext();Thread.UncaughtExceptionHandler previous=Thread.getDefaultUncaughtExceptionHandler();Thread.setDefaultUncaughtExceptionHandler((thread,error)->{try{if(crashing.compareAndSet(false,true))record(app,"CRASH",error,true);}catch(Throwable ignored){}finally{if(previous!=null)previous.uncaughtException(thread,error);else{android.os.Process.killProcess(android.os.Process.myPid());System.exit(10);}}});application.registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){if(a instanceof MainActivity){resumed=new WeakReference<>(a);main.postDelayed(()->offer(a),350);}}public void onActivityPaused(Activity a){if(resumed.get()==a)resumed.clear();}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}});}
 private static AtomicFile file(Context c){return new AtomicFile(new File(c.getNoBackupFilesDir(),"latest-issue.json"));}
 private static synchronized JSONObject load(Context c){try(var in=file(c).openRead()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[1024];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>32768)return new JSONObject();out.write(bytes,0,n);}return new JSONObject(out.toString("UTF-8"));}catch(Exception ignored){return new JSONObject();}}
 private static synchronized void save(Context c,JSONObject data){AtomicFile f=file(c);FileOutputStream out=null;try{byte[] bytes=data.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);if(bytes.length>32768)return;out=f.startWrite();out.write(bytes);f.finishWrite(out);}catch(Exception ignored){if(out!=null)f.failWrite(out);}}
 static String description(String code){return switch(code){case "ROOT_SETUP"->"เตรียมส่วนเสริมไม่สำเร็จ";case "OPEN_TIMEOUT"->"ยังยืนยันการเปิดงานไม่ได้";case "OPEN_LAUNCH"->"เปิดงานจากเบื้องหลังไม่สำเร็จ";case "CRASH"->"แอปหยุดทำงานครั้งก่อน";default->"พบปัญหาการทำงาน";};}
 static synchronized void record(Context c,String code,Throwable error,boolean notify){if(!java.util.Set.of("ROOT_SETUP","OPEN_TIMEOUT","OPEN_LAUNCH","CRASH").contains(code))return;try{JSONObject old=load(c);long now=System.currentTimeMillis();StringBuilder trace=new StringBuilder();Throwable cause=error;for(int depth=0;cause!=null&&depth<4;depth++,cause=cause.getCause()){trace.append(cause.getClass().getName()).append('\n');int count=0;for(StackTraceElement e:cause.getStackTrace())if(e.getClassName().startsWith("com.fulllock.")&&count++<16)trace.append("  ").append(e.getClassName()).append('.').append(e.getMethodName()).append(':').append(e.getLineNumber()).append('\n');}String fingerprint=code+trace;boolean duplicate=fingerprint.equals(old.optString("fingerprint"))&&now>=old.optLong("time")&&now-old.optLong("time")<86400000;JSONObject data=new JSONObject();data.put("id",duplicate?old.optString("id"):java.util.UUID.randomUUID().toString().substring(0,8));data.put("code",code);data.put("time",now);data.put("count",duplicate?old.optInt("count",1)+1:1);data.put("fingerprint",fingerprint);data.put("pending",notify&&(!duplicate||old.optBoolean("pending")));String probe="not-installed";try{probe=c.getPackageManager().getPackageInfo("com.gozza.lalamove",0).versionName;}catch(Exception ignored){}String report="Gozza Lalamove issue "+data.getString("id")+"\n"+code+" · "+description(code)+"\nTime: "+new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss Z",java.util.Locale.ROOT).format(new java.util.Date(now))+"\nApp: "+BuildConfig.VERSION_NAME+" ("+BuildConfig.VERSION_CODE+")\nAndroid: "+Build.VERSION.RELEASE+" / API "+Build.VERSION.SDK_INT+"\nDevice: "+Build.MANUFACTURER+" "+Build.MODEL+"\nProbe: "+probe+"\nRoot setup step: "+RootSetup.stage+"\nFramework check: "+RootSetup.frameworkStatus+"\nRoot mode: "+RootMode.enabled(c)+" / preparing: "+RootSetup.updatePending+"\nProbe connected: "+DriverBridge.probeConnected()+"\nNotification listener: "+JobListener.connected+" / permission: "+PermissionSetup.reading(c)+"\nOverlay permission: "+android.provider.Settings.canDrawOverlays(c)+"\nStarted: "+Store.prefs(c).getBoolean("enabled",false)+" / auto accept: "+Store.prefs(c).getBoolean("autoAccept",false)+"\n"+trace;data.put("report",report);save(c,data);if(notify&&!code.equals("CRASH"))main.post(()->{Activity a=resumed.get();if(a!=null)offer(a);});}catch(Exception ignored){}}
 static void interrupted(Context c){if(!load(c).optString("code").equals("CRASH"))record(c,"OPEN_TIMEOUT",null,true);}
 static String report(Context c){JSONObject d=load(c);return d.optString("report","")+(d.has("count")?"\nOccurrences: "+d.optInt("count",1):"");}
 static String summary(Context c){JSONObject d=load(c);return d.has("code")?description(d.optString("code"))+" · "+d.optString("id"):"ยังไม่มีข้อมูลปัญหา";}
 static void copy(Context c){String text=report(c);if(text.isEmpty())return;c.getSystemService(ClipboardManager.class).setPrimaryClip(ClipData.newPlainText("Gozza Lalamove log",text));Toast.makeText(c,"คัดลอก log แล้ว",Toast.LENGTH_SHORT).show();}
 static void details(Activity a){String text=report(a);if(text.isEmpty()){Toast.makeText(a,"ยังไม่มีข้อมูลปัญหา",Toast.LENGTH_SHORT).show();return;}TextView t=new TextView(a);t.setText(text);t.setTextColor(AppTheme.ink(a));t.setTextSize(12);t.setTextIsSelectable(true);t.setPadding(28,16,28,16);ScrollView scroll=new ScrollView(a);scroll.addView(t);AlertDialog d=new AlertDialog.Builder(a).setTitle("ข้อมูลปัญหาล่าสุด").setView(scroll).setPositiveButton("คัดลอก log",(v,w)->copy(a)).setNegativeButton("ปิด",null).show();AppTheme.styleDialog(a,d);}
 private static void offer(Activity a){if(showing||a.isFinishing()||a.isDestroyed()||!a.hasWindowFocus())return;JSONObject d=load(a);if(!d.optBoolean("pending"))return;try{showing=true;String id=d.optString("id");AlertDialog dialog=new AlertDialog.Builder(a).setTitle("พบปัญหาการทำงาน").setMessage(description(d.optString("code"))+"\n\nคัดลอกข้อมูลปัญหาเพื่อส่งให้ PHANToM ตรวจสอบ\nดูย้อนหลังได้ที่ ตรวจสอบระบบ").setPositiveButton("คัดลอก log",(v,w)->copy(a)).setNegativeButton("ปิด",null).create();activeDialog=dialog;dialog.setOnDismissListener(v->{showing=false;activeDialog=null;ack(a,id);});dialog.show();AppTheme.styleDialog(a,dialog);}catch(Exception ignored){showing=false;}}
 private static synchronized void ack(Context c,String id){JSONObject d=load(c);if(!id.equals(d.optString("id")))return;try{d.put("pending",false);save(c,d);}catch(Exception ignored){}}
}
